//! Composition admission must preserve ordinary Choreo samples, not a golden
//! generated by the parallel implementation itself.
use fmn_anim::pure_frame::{PureFrameRefusal, PureSegment};
use fmn_anim::{
    AnimConfig, AnimState, Animation, AnimationGroup, AnimationSignature, RateFunc,
    RationalFrameClock, Succession, Transform, advance_play, finish_open_play, open_play,
};
use fmn_core::rate::CatalogRate;
use fmn_core::rng::RngRoot;
use fmn_mobject::{Mob, Mobject, Snapshot, Stage};

fn object(stage: &mut Stage, x: f64) -> Mob {
    let mob = stage.add(Mobject::from_points(&[[x, 0.0, 0.0], [x + 1.0, 1.0, 0.0]]));
    stage.add_to_scene(mob).unwrap();
    mob
}

fn transform(stage: &mut Stage, x: f64, run_time: f64) -> Box<dyn Animation> {
    let mob = object(stage, x);
    let target = stage.copy_family(mob).unwrap();
    stage.shift(target, [2.0, 1.0, 0.5]);
    Box::new(Transform::new(mob, target).with_config(AnimConfig {
        run_time,
        rate_func: RateFunc::Catalog(CatalogRate::ThereAndBack),
        ..AnimConfig::default()
    }))
}

fn facts(stage: &Stage) -> Vec<String> {
    let mut facts = vec![format!("time {:x}", stage.time().to_bits())];
    for &root in stage.roots() {
        let family = stage.family(root);
        facts.push(format!("family {}", family.len()));
        for mob in family {
            let entry = stage.get(mob).unwrap();
            facts.push(format!(
                "{:?}",
                entry.placement().coefficients().map(f64::to_bits)
            ));
            facts.push(format!(
                "{:?}/{:?}/{:?}",
                entry.uniforms(),
                stage.tracker(mob),
                (stage.is_animating(mob), stage.is_updating_suspended(mob))
            ));
            for field in entry.buffer.schema().fields() {
                let bits: Vec<_> = entry
                    .buffer
                    .read_column(&field.name)
                    .unwrap()
                    .iter()
                    .map(|value| value.to_bits())
                    .collect();
                facts.push(format!("{}:{bits:?}", field.name));
            }
        }
    }
    facts
}

fn compare(mut stage: Stage, mut animations: Vec<Box<dyn Animation>>) {
    let rng = RngRoot::from_seed(61);
    let mut clock = RationalFrameClock::new(30).unwrap();
    clock.advance_frames(7).unwrap();
    stage.set_time_from_clock(clock.now().to_f64());
    let mut open = open_play(&mut stage, &clock, &mut animations).unwrap();
    let program = PureSegment::freeze(&stage, &clock, &rng, &animations, &open).unwrap();
    let mut expected = Vec::new();
    advance_play(
        &mut stage,
        &mut clock,
        &rng,
        &mut animations,
        &mut open,
        program.frame_count(),
        &mut |packet| {
            expected.push((
                facts(&packet.materialize_stage()),
                packet.rng_fork("groups").next_u64(),
            ));
        },
    )
    .unwrap();
    assert!(!expected.is_empty());
    for workers in [1, 4, 16] {
        std::thread::scope(|scope| {
            for worker in 0..workers {
                let program = &program;
                let expected = &expected;
                scope.spawn(move || {
                    for index in (worker..expected.len()).step_by(workers).rev() {
                        let job = program.job(index as i64 + 1).unwrap();
                        assert_eq!(
                            facts(&job.materialize()),
                            expected[index].0,
                            "workers={workers}, frame={index}"
                        );
                        assert_eq!(job.rng_fork("groups").next_u64(), expected[index].1);
                    }
                });
            }
        });
    }
    finish_open_play(&mut stage, &mut animations, open).unwrap();
}

#[test]
fn native_frame_groups_match_serial_sampling_on_every_worker_count() {
    let mut stage = Stage::new();
    let mut members = vec![
        transform(&mut stage, -4.0, 1.0),
        transform(&mut stage, 0.0, 1.0),
        transform(&mut stage, 4.0, 1.0),
    ];
    for (member, frames) in members.iter_mut().zip([29, 38, 0]) {
        member.state_mut().config.run_time_frames = Some(frames);
    }
    let inner = AnimationGroup::with_lag_ratio(&mut stage, members, 1.0).unwrap();
    let outer = AnimationGroup::new(&mut stage, vec![Box::new(inner)])
        .unwrap()
        .with_run_time_frames(67);
    compare(stage, vec![Box::new(outer)]);
}

#[test]
fn mixed_and_large_exact_group_endpoints_match_serial_and_frozen_dispatch() {
    use fmn_anim::rate_table::RateSampler;

    for large in [false, true] {
        for group_rate in [RateFunc::linear(), RateFunc::Base(fmn_core::rate::linear)] {
            let mut stage = Stage::new();
            let source = object(&mut stage, 0.0);
            let target = stage.copy_family(source).unwrap();
            stage.shift(target, [2.0, 0.0, 0.0]);
            let sampler = RateSampler::new(3, |alpha| Ok(if alpha == 1.0 { 1.0 } else { 0.0 }));
            let preparing = RateFunc::Preparing(sampler.clone());
            for alpha in [0.0, 1.0_f64.next_down(), 1.0] {
                let _ = preparing.eval(alpha);
            }
            let boundary = if large { (1_i64 << 53) + 1 } else { 44 };
            let first = Transform::new(source, target).with_config(AnimConfig {
                run_time: 43.0 / 24.0,
                run_time_frames: large.then_some(boundary as u64),
                rate_func: sampler.finish().unwrap(),
                ..AnimConfig::default()
            });
            let mut second = transform(&mut stage, 4.0, 1.0);
            second.state_mut().config.run_time_frames = Some(1);
            let inner =
                AnimationGroup::with_lag_ratio(&mut stage, vec![Box::new(first), second], 1.0)
                    .unwrap()
                    .with_rate_func(group_rate);
            let outer = AnimationGroup::new(&mut stage, vec![Box::new(inner)]).unwrap();
            let mut animations: Vec<Box<dyn Animation>> = vec![Box::new(outer)];
            let clock = RationalFrameClock::new(24).unwrap();
            let rng = RngRoot::from_seed(61);
            let open = open_play(&mut stage, &clock, &mut animations).unwrap();
            let program = PureSegment::freeze(&stage, &clock, &rng, &animations, &open).unwrap();

            // Direct jobs and snapshot reconstruction make both large-index
            // samples O(1); the test never loops over the intervening frames.
            for (frame, expected_x) in [(boundary - 1, 0.5), (boundary, 2.5)] {
                let job = program.job(frame).unwrap();
                let packet = fmn_anim::reconstruct_pure_frame(
                    &mut stage,
                    &mut animations,
                    open.report(),
                    &rng,
                    &job.sample(),
                )
                .unwrap();
                let serial = packet.materialize_stage();
                let frozen = job.try_materialize().unwrap();
                assert_eq!(serial.get_center(source)[0], expected_x);
                assert_eq!(frozen.get_center(source)[0], expected_x);
                assert_eq!(facts(&frozen), facts(&serial));
            }
            finish_open_play(&mut stage, &mut animations, open).unwrap();
        }
    }
}

#[test]
fn zero_frame_dispatch_runs_only_lifecycle_rate_samples() {
    use fmn_anim::pure_frame::{PlayCapture, play_segment_with_pure_dispatch};

    #[derive(Default)]
    struct Capture {
        packets: usize,
        programs: usize,
    }
    impl PlayCapture for Capture {
        fn capture(&mut self, _packet: fmn_anim::FramePacket) {
            self.packets += 1;
        }
        fn accepts_pure_segments(&self) -> bool {
            true
        }
        fn capture_pure_segment(&mut self, _segment: &PureSegment) -> bool {
            self.programs += 1;
            true
        }
    }

    let sampler = fmn_anim::rate_table::RateSampler::new(2, Ok);
    let preparing = RateFunc::Preparing(sampler.clone());
    assert_eq!(preparing.eval(0.0), 0.0);
    assert_eq!(preparing.eval(1.0), 1.0);
    let exact = sampler.finish().unwrap();
    for (skip, allow_pure) in [(false, false), (false, true), (true, false), (true, true)] {
        let mut stage = Stage::new();
        let mut animation = transform(&mut stage, 0.0, 1.0);
        let mob = animation.state().mobject();
        animation.state_mut().config.run_time_frames = Some(0);
        animation.state_mut().config.rate_func = exact.clone();
        let mut animations = vec![animation];
        let mut clock = RationalFrameClock::new(24).unwrap();
        let mut capture = Capture::default();
        let mut boundaries = 0;
        let report = play_segment_with_pure_dispatch(
            &mut stage,
            &mut clock,
            &RngRoot::from_seed(10),
            &mut animations,
            skip,
            allow_pure,
            &mut |_, _| boundaries += 1,
            &mut capture,
        )
        .unwrap();
        assert_eq!(report.n_frames, 0);
        assert_eq!(clock.now().frames(), 0);
        assert_eq!((capture.packets, capture.programs, boundaries), (0, 0, 0));
        assert!(animations[0].state().starting_mobject().is_some());
        assert_eq!(stage.get_center(mob), [2.5, 1.5, 0.5]);
        assert!(!stage.is_animating(mob));
        assert!(!stage.is_updating_suspended(mob));
        assert_eq!(animations[0].deferred_error(), None);
    }
}

#[test]
fn nested_lagged_groups_keep_unequal_durations_rates_and_time_spans() {
    for lag in [0.0, 0.3, 1.0] {
        let mut stage = Stage::new();
        let members = vec![
            transform(&mut stage, -4.0, 0.2),
            transform(&mut stage, 0.0, 0.35),
            transform(&mut stage, 4.0, 0.0),
        ];
        let mut inner = AnimationGroup::with_lag_ratio(&mut stage, members, lag)
            .unwrap()
            .with_run_time(0.5)
            .with_rate_func(RateFunc::Catalog(CatalogRate::ThereAndBack).squish(0.1, 0.9));
        inner.state_mut().config.time_span = Some((0.05, 0.55));
        let other = transform(&mut stage, 8.0, 0.4);
        let outer = AnimationGroup::with_lag_ratio(&mut stage, vec![Box::new(inner), other], 0.2)
            .unwrap()
            .with_run_time(0.8);
        compare(stage, vec![Box::new(outer)]);
    }
}

#[test]
fn empty_groups_with_explicit_duration_have_the_serial_static_frames() {
    let mut stage = Stage::new();
    object(&mut stage, 0.0);
    let group = AnimationGroup::new(&mut stage, Vec::new())
        .unwrap()
        .with_run_time(0.2);
    compare(stage, vec![Box::new(group)]);
}

fn refusal(stage: &mut Stage, animations: &mut [Box<dyn Animation>]) -> PureFrameRefusal {
    let clock = RationalFrameClock::new(30).unwrap();
    let open = open_play(stage, &clock, animations).unwrap();
    let result =
        PureSegment::freeze(stage, &clock, &RngRoot::from_seed(61), animations, &open).unwrap_err();
    finish_open_play(stage, animations, open).unwrap();
    result
}

#[test]
fn nested_custom_group_rate_remains_on_the_owner() {
    fn custom(alpha: f64) -> f64 {
        alpha * alpha
    }
    let mut stage = Stage::new();
    let member = transform(&mut stage, 0.0, 0.2);
    let inner = AnimationGroup::new(&mut stage, vec![member])
        .unwrap()
        .with_rate_func(RateFunc::Base(custom));
    let outer = AnimationGroup::new(&mut stage, vec![Box::new(inner)]).unwrap();
    assert_eq!(
        refusal(&mut stage, &mut [Box::new(outer)]),
        PureFrameRefusal::UnsupportedAnimation(0)
    );
}

#[test]
fn aliases_between_nested_groups_are_not_hidden_by_empty_container_families() {
    let mut stage = Stage::new();
    let mob = object(&mut stage, 0.0);
    let first = stage.copy_family(mob).unwrap();
    let second = stage.copy_family(mob).unwrap();
    stage.shift(first, [1.0, 0.0, 0.0]);
    stage.shift(second, [0.0, 1.0, 0.0]);
    let left = AnimationGroup::new(&mut stage, vec![Box::new(Transform::new(mob, first))]).unwrap();
    let right =
        AnimationGroup::new(&mut stage, vec![Box::new(Transform::new(mob, second))]).unwrap();
    let outer = AnimationGroup::new(&mut stage, vec![Box::new(left), Box::new(right)]).unwrap();
    assert_eq!(
        refusal(&mut stage, &mut [Box::new(outer)]),
        PureFrameRefusal::OverlappingOutput(mob)
    );
}

#[test]
fn a_group_cannot_read_a_target_written_by_another_top_level_animation() {
    let mut stage = Stage::new();
    let a = object(&mut stage, 0.0);
    // Identical object-space geometry retains the live target rather than
    // taking the independent geometry-baking copy used by a shape morph.
    let b = stage.copy_family(a).unwrap();
    stage.shift(b, [3.0, 0.0, 0.0]);
    let c = stage.copy_family(b).unwrap();
    stage.shift(c, [0.0, 2.0, 0.0]);
    let group = AnimationGroup::new(&mut stage, vec![Box::new(Transform::new(a, b))]).unwrap();
    let mut animations: Vec<Box<dyn Animation>> =
        vec![Box::new(group), Box::new(Transform::new(b, c))];
    assert_eq!(
        refusal(&mut stage, &mut animations),
        PureFrameRefusal::MutableEndpoint(b)
    );
}

struct Opaque(AnimState);
impl Animation for Opaque {
    fn state(&self) -> &AnimState {
        &self.0
    }
    fn state_mut(&mut self) -> &mut AnimState {
        &mut self.0
    }
    fn effect_signature(&self) -> AnimationSignature {
        AnimationSignature::Pure
    }
    fn interpolate_submobject(&mut self, _: &mut Stage, _: &[Mob], _: f64) {}
}

#[test]
fn a_purity_claim_does_not_admit_an_unknown_nested_mechanism() {
    let mut stage = Stage::new();
    let mob = object(&mut stage, 0.0);
    let opaque = Opaque(AnimState::new(mob, AnimConfig::default()));
    let group = AnimationGroup::new(&mut stage, vec![Box::new(opaque)]).unwrap();
    assert_eq!(
        refusal(&mut stage, &mut [Box::new(group)]),
        PureFrameRefusal::UnsupportedAnimation(0)
    );
}

#[test]
fn just_in_time_succession_is_not_mistaken_for_an_eager_group() {
    let mut stage = Stage::new();
    let first = transform(&mut stage, 0.0, 0.2);
    let second = transform(&mut stage, 3.0, 0.2);
    let succession = Succession::new(&mut stage, vec![first, second]).unwrap();
    let group = AnimationGroup::new(&mut stage, vec![Box::new(succession)]).unwrap();
    assert!(matches!(
        refusal(&mut stage, &mut [Box::new(group)]),
        PureFrameRefusal::NotAtPureBegin | PureFrameRefusal::UnsupportedAnimation(0)
    ));
}

#[test]
fn nested_endpoint_live_views_and_updaters_still_demote() {
    for updater in [false, true] {
        let mut stage = Stage::new();
        let mob = object(&mut stage, 0.0);
        let target = stage.copy_family(mob).unwrap();
        stage.shift(target, [1.0, 0.0, 0.0]);
        let view = if updater {
            stage.add_dt_updater(target, |_, _, _| {}, false).unwrap();
            None
        } else {
            Some(stage.get_mut(target).unwrap().buffer.export_view(false))
        };
        let child =
            AnimationGroup::new(&mut stage, vec![Box::new(Transform::new(mob, target))]).unwrap();
        let group = AnimationGroup::new(&mut stage, vec![Box::new(child)]).unwrap();
        let result = refusal(&mut stage, &mut [Box::new(group)]);
        if updater {
            assert_eq!(result, PureFrameRefusal::NotAtPureBegin);
        } else {
            assert_eq!(result, PureFrameRefusal::LiveView(target));
        }
        drop(view);
    }
}

fn cleanup_scene() -> (Stage, Vec<Box<dyn Animation>>) {
    let mut stage = Stage::new();
    let mob = object(&mut stage, 0.0);
    let target = stage.copy_family(mob).unwrap();
    stage.shift(target, [2.0, 0.0, 0.0]);
    let member = Transform::new(mob, target).with_config(AnimConfig {
        run_time: 0.2,
        final_alpha_value: 0.4,
        remover: true,
        ..AnimConfig::default()
    });
    let inner = AnimationGroup::new(&mut stage, vec![Box::new(member)]).unwrap();
    let other = transform(&mut stage, -3.0, 0.35);
    let group =
        AnimationGroup::with_lag_ratio(&mut stage, vec![Box::new(inner), other], 0.3).unwrap();
    (stage, vec![Box::new(group)])
}

#[test]
fn group_owner_completion_keeps_member_final_alpha_removal_and_clock() {
    let (mut serial, mut serial_animations) = cleanup_scene();
    let (mut native, mut native_animations) = cleanup_scene();
    let mut serial_clock = RationalFrameClock::new(30).unwrap();
    let mut native_clock = RationalFrameClock::new(30).unwrap();
    let rng = RngRoot::from_seed(91);
    let mut serial_open = open_play(&mut serial, &serial_clock, &mut serial_animations).unwrap();
    let native_open = open_play(&mut native, &native_clock, &mut native_animations).unwrap();
    let program = PureSegment::freeze(
        &native,
        &native_clock,
        &rng,
        &native_animations,
        &native_open,
    )
    .unwrap();
    advance_play(
        &mut serial,
        &mut serial_clock,
        &rng,
        &mut serial_animations,
        &mut serial_open,
        program.frame_count(),
        &mut |_| {},
    )
    .unwrap();
    finish_open_play(&mut serial, &mut serial_animations, serial_open).unwrap();
    for frame in (1..=program.frame_count()).rev() {
        let _ = program.job(frame).unwrap().materialize();
    }
    program
        .finish_on_owner(
            &mut native,
            &mut native_clock,
            &mut native_animations,
            native_open,
        )
        .unwrap();
    assert_eq!(facts(&native), facts(&serial));
    assert_eq!(native_clock.now(), serial_clock.now());
}

fn durable_group_scene(case: usize) -> (Stage, Vec<Box<dyn Animation>>) {
    if case == 4 {
        return cleanup_scene();
    }
    let mut stage = Stage::new();
    let mut members = vec![
        transform(&mut stage, -4.0, 0.2),
        transform(&mut stage, 0.0, 0.35),
        transform(&mut stage, 4.0, 0.0),
    ];
    if case == 0 {
        for (member, frames) in members.iter_mut().zip([29, 38, 0]) {
            member.state_mut().config.run_time_frames = Some(frames);
        }
        let inner = AnimationGroup::with_lag_ratio(&mut stage, members, 1.0).unwrap();
        let outer = AnimationGroup::new(&mut stage, vec![Box::new(inner)])
            .unwrap()
            .with_run_time_frames(67);
        return (stage, vec![Box::new(outer)]);
    }
    if case == 3 {
        let empty = AnimationGroup::new(&mut stage, Vec::new())
            .unwrap()
            .with_run_time_frames(11);
        members.push(Box::new(empty));
    }
    if case == 1 {
        members[0].state_mut().config.run_time_frames = Some(7);
    }
    let mut inner = AnimationGroup::with_lag_ratio(&mut stage, members, 0.3)
        .unwrap()
        .with_duration_scale(1.3)
        .with_rate_func(RateFunc::Catalog(CatalogRate::ThereAndBack).squish(0.1, 0.9));
    if case == 2 {
        inner = inner.with_run_time(0.5);
        inner.state_mut().config.time_span = Some((0.05, 0.55));
    }
    let other = transform(&mut stage, 8.0, 0.4);
    let mut outer =
        AnimationGroup::with_lag_ratio(&mut stage, vec![Box::new(inner), other], 0.2).unwrap();
    if case == 1 {
        outer = outer.with_duration_scale(1.35);
    } else {
        outer = outer.with_run_time(0.8);
    }
    (stage, vec![Box::new(outer)])
}

#[test]
fn durable_nested_groups_resume_exact_timing_and_remaining_lifecycles() {
    let rng = RngRoot::from_seed(91);
    for case in 0..5 {
        for boundary in 0..5 {
            let (mut serial, mut animations) = durable_group_scene(case);
            let mut clock = RationalFrameClock::new(30).unwrap();
            clock.advance_frames(7).unwrap();
            serial.set_time_from_clock(clock.now().to_f64());
            let mut open = open_play(&mut serial, &clock, &mut animations).unwrap();
            let total = open.report().n_frames;
            let frame = [0, 1, total / 2, total - 1, total][boundary];
            advance_play(
                &mut serial,
                &mut clock,
                &rng,
                &mut animations,
                &mut open,
                frame,
                &mut |_| {},
            )
            .unwrap();
            let checkpoint =
                fmn_anim::continuation::capture(&serial, &clock, &animations, &open, 1024 * 1024)
                    .unwrap()
                    .expect("closed eager groups have a durable native lifecycle");
            let snapshot = serial.snapshot().to_bytes().unwrap();
            let mut restored = Stage::new();
            let decoded = Snapshot::from_bytes(&snapshot, &restored).unwrap();
            restored.restore(&decoded.snapshot);
            // Arena snapshots exclude the runtime clock. Reinstall its Stage
            // mirror as Scene::apply_state does, including when no frames remain.
            restored.set_time_from_clock(clock.now().to_f64());
            let (mut resumed, mut resumed_open) =
                fmn_anim::continuation::restore(&restored, &clock, &checkpoint).unwrap();
            let mut resumed_clock = clock;
            assert_eq!(restored.snapshot().to_bytes().unwrap(), snapshot);
            assert_eq!(facts(&restored), facts(&serial));
            assert_eq!(
                fmn_anim::continuation::capture(
                    &restored,
                    &resumed_clock,
                    &resumed,
                    &resumed_open,
                    1024 * 1024,
                )
                .unwrap()
                .unwrap(),
                checkpoint,
                "case={case}, frame={frame}: nested prepared timing identity"
            );
            let mut expected_frames = Vec::new();
            let mut resumed_frames = Vec::new();
            advance_play(
                &mut serial,
                &mut clock,
                &rng,
                &mut animations,
                &mut open,
                total,
                &mut |packet| expected_frames.push(facts(&packet.materialize_stage())),
            )
            .unwrap();
            advance_play(
                &mut restored,
                &mut resumed_clock,
                &rng,
                &mut resumed,
                &mut resumed_open,
                total,
                &mut |packet| resumed_frames.push(facts(&packet.materialize_stage())),
            )
            .unwrap();
            assert_eq!(
                resumed_frames, expected_frames,
                "case={case}, frame={frame}"
            );
            finish_open_play(&mut serial, &mut animations, open).unwrap();
            finish_open_play(&mut restored, &mut resumed, resumed_open).unwrap();
            assert_eq!(
                facts(&restored),
                facts(&serial),
                "case={case}, frame={frame}"
            );
            assert_eq!(resumed_clock.now(), clock.now());
        }
    }
}

#[test]
fn durable_group_reconstruction_preserves_frame_boundaries_above_f64_precision() {
    let mut stage = Stage::new();
    let boundary = (1_i64 << 53) + 1;
    let mut first = transform(&mut stage, 0.0, 1.0);
    first.state_mut().config.run_time_frames = Some(boundary as u64);
    first.state_mut().config.rate_func = RateFunc::linear();
    let mut second = transform(&mut stage, 4.0, 1.0);
    second.state_mut().config.run_time_frames = Some(1);
    second.state_mut().config.rate_func = RateFunc::linear();
    let inner = AnimationGroup::with_lag_ratio(&mut stage, vec![first, second], 1.0).unwrap();
    let outer = AnimationGroup::new(&mut stage, vec![Box::new(inner)]).unwrap();
    let mut animations: Vec<Box<dyn Animation>> = vec![Box::new(outer)];
    let clock = RationalFrameClock::new(24).unwrap();
    let open = open_play(&mut stage, &clock, &mut animations).unwrap();
    let checkpoint =
        fmn_anim::continuation::capture(&stage, &clock, &animations, &open, 1024 * 1024)
            .unwrap()
            .unwrap();
    let mut restored = Stage::new();
    let decoded = Snapshot::from_bytes(&stage.snapshot().to_bytes().unwrap(), &restored).unwrap();
    restored.restore(&decoded.snapshot);
    let (mut resumed, resumed_open) =
        fmn_anim::continuation::restore(&restored, &clock, &checkpoint).unwrap();
    for frame in [boundary - 1, boundary, boundary + 1] {
        let position = fmn_anim::FramePosition::from_frame(frame);
        animations[0]
            .interpolate_at_position(&mut stage, &position, 24)
            .unwrap();
        resumed[0]
            .interpolate_at_position(&mut restored, &position, 24)
            .unwrap();
        assert_eq!(facts(&restored), facts(&stage), "frame={frame}");
    }
    finish_open_play(&mut stage, &mut animations, open).unwrap();
    finish_open_play(&mut restored, &mut resumed, resumed_open).unwrap();
    assert_eq!(facts(&restored), facts(&stage));
}

#[test]
fn durable_group_declarations_bind_nested_controls_and_refuse_unknown_children() {
    use fmn_anim::continuation::{DeclarationOverrides, declaration_bytes};

    let (stage, animations) = durable_group_scene(1);
    let declared = declaration_bytes(
        &stage,
        &animations,
        DeclarationOverrides::default(),
        1024 * 1024,
    )
    .unwrap()
    .unwrap();
    let retimed = declaration_bytes(
        &stage,
        &animations,
        DeclarationOverrides {
            run_time_frames: Some(81),
            ..DeclarationOverrides::default()
        },
        1024 * 1024,
    )
    .unwrap()
    .unwrap();
    assert_ne!(declared, retimed);
    let mut stage = Stage::new();
    let mob = object(&mut stage, 0.0);
    let opaque = Opaque(AnimState::new(mob, AnimConfig::default()));
    let inner = AnimationGroup::new(&mut stage, vec![Box::new(opaque)]).unwrap();
    let outer = AnimationGroup::new(&mut stage, vec![Box::new(inner)]).unwrap();
    let before = stage.snapshot().to_bytes().unwrap();
    assert!(
        declaration_bytes(
            &stage,
            &[Box::new(outer)],
            DeclarationOverrides::default(),
            1024 * 1024,
        )
        .unwrap()
        .is_none()
    );
    assert_eq!(stage.snapshot().to_bytes().unwrap(), before);
}
